'use strict';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('en-GB').format(Math.round(n));
const cards=[
{id:'263620',name:'Romeo Lavia',short:'Lavia',rating:78,position:'CDM',rarity:'Gold rare',club:'Chelsea',nation:'Belgium',price:850,change:-6.2,image:'assets/lavia.webp',stats:[66,52,74,78,77,72]},
{id:'263745',name:'Christian Witzig',short:'Witzig',rating:71,position:'LM',rarity:'Silver rare',club:'St. Gallen',nation:'Switzerland',price:400,change:7.4,image:'assets/witzig.webp',stats:[72,65,70,73,61,69]},
{id:'demo-patri',name:'Patri Guijarro',short:'Patri',rating:89,position:'CM',rarity:'Demo gold item',club:'Barcelona',nation:'Spain',price:278000,change:-3.1,stats:[75,82,89,87,87,83]},
{id:'demo-jude',name:'Jude Bellingham',short:'Bellingham',rating:90,position:'CAM',rarity:'Demo gold item',club:'Real Madrid',nation:'England',price:1240000,change:4.8,stats:[82,88,87,89,78,84]},
{id:'demo-yamal',name:'Lamine Yamal',short:'Yamal',rating:89,position:'RW',rarity:'Demo gold item',club:'Barcelona',nation:'Spain',price:492000,change:8.2,stats:[88,83,86,94,29,54]},
{id:'demo-vvd',name:'Virgil van Dijk',short:'Van Dijk',rating:89,position:'CB',rarity:'Demo gold item',club:'Liverpool',nation:'Netherlands',price:185000,change:-5.4,stats:[76,60,72,72,90,87]},
{id:'demo-palmer',name:'Cole Palmer',short:'Palmer',rating:87,position:'CAM',rarity:'Demo gold item',club:'Chelsea',nation:'England',price:98500,change:2.7,stats:[77,88,87,90,45,67]},
{id:'demo-saliba',name:'William Saliba',short:'Saliba',rating:87,position:'CB',rarity:'Demo gold item',club:'Arsenal',nation:'France',price:66500,change:-1.8,stats:[82,40,65,70,89,83]}];
const defaultState={watch:['263620','demo-patri','demo-vvd'],alerts:[{id:'a1',card:'demo-patri',direction:'below',target:255000,state:'active'},{id:'a2',card:'263620',direction:'below',target:750,state:'active'},{id:'a3',card:'demo-yamal',direction:'above',target:510000,state:'paused'}],feeds:[{id:'f1',name:'Official FC updates',provider:'X account',source:'@EASPORTSFC',channel:'fc-news',enabled:true},{id:'f2',name:'Community leaks',provider:'RSS / Atom',source:'Example FC leaks source',channel:'leaks-and-rumours',enabled:true},{id:'f3',name:'Creator uploads',provider:'YouTube',source:'Example creator channel',channel:'creator-content',enabled:false}],brand:{name:'FutBot',accent:'#1638c5',footer:'FutBot • Ultimate Team tools'}};
let saved;try{saved=JSON.parse(localStorage.getItem('futbot-v1'));}catch{}
let state=saved&&Array.isArray(saved.alerts)&&Array.isArray(saved.watch)&&Array.isArray(saved.feeds)&&saved.brand?saved:structuredClone(defaultState);
if(['#c2f970','#29eaff'].includes(state.brand.accent))state.brand.accent='#1638c5';
let selected='263620',timeframe='24h',query='',sort='all',toastTimer;const names={overview:'Overview',players:'Player explorer',alerts:'Price alerts',watchlist:'Watchlist',market:'Market movers',feeds:'News feeds',appearance:'Appearance',health:'Data & connections'};
const card=id=>cards.find(c=>c.id===id)||cards[0];
function persist(){try{localStorage.setItem('futbot-v1',JSON.stringify(state));}catch{toast('Browser storage is unavailable. Changes will last for this session.');}$('#alert-count').textContent=state.alerts.filter(a=>a.state==='active').length;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function applyBrand(){const colour=/^#[0-9a-f]{6}$/i.test(state.brand.accent)?state.brand.accent:'#1638c5';document.documentElement.style.setProperty('--accent',colour);}
function art(c,klass='card-art'){return c.image?`<img class="${klass}" src="${c.image}" alt="${esc(c.name)} ${c.rating} card artwork" loading="lazy">`:`<span class="${klass==='table-art'?'placeholder-art':'big-placeholder'}" aria-label="Illustrative card placeholder">${c.rating}</span>`;}
function movement(c){return `<span class="${c.change>=0?'positive':'negative'}">${c.change>=0?'↗ +':'↘ '}${c.change.toFixed(1)}%</span>`;}
function series(c,tf=timeframe){let seed=c.id.split('').reduce((a,v)=>a+v.charCodeAt(0),0);const n=tf==='7d'?36:tf==='6h'?18:30;const start=c.price/(1+c.change/100);return Array.from({length:n},(_,i)=>{seed=(seed*16807)%2147483647;const progress=i/(n-1);return Math.round(start+(c.price-start)*progress+(seed/2147483647-.5)*c.price*.035*(i===n-1?0:1));});}
function svgChart(c,mini=false){const values=series(c),min=Math.min(...values)*.99,max=Math.max(...values)*1.01;const w=mini?90:600,h=mini?28:160,pad=mini?2:13;const points=values.map((v,i)=>[pad+i/(values.length-1)*(w-pad*2),h-pad-(v-min)/(max-min)*(h-pad*2)]);const d=points.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ');const colour=c.change>=0?'var(--accent)':'var(--coral)';return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Illustrative ${esc(timeframe)} price trend for ${esc(c.name)}">${mini?'':`<path d="M13 25H587M13 75H587M13 125H587" stroke="#493058" stroke-width="1" stroke-dasharray="3 5"/><path d="${d} L${w-pad},${h} L${pad},${h} Z" fill="${colour}" opacity=".055"/>`}<path d="${d}" fill="none" stroke="${colour}" stroke-width="${mini?2:2.4}" stroke-linecap="round" stroke-linejoin="round"/>${mini?'':`<circle cx="${points.at(-1)[0]}" cy="${points.at(-1)[1]}" r="3.5" fill="${colour}"/>`}</svg>`;}
function header(eyebrow,title,desc,action=''){return `<div class="page-header"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="muted">${desc}</p></div>${action}</div>`;}
function watchButton(c){const saved=state.watch.includes(c.id);return `<button class="watch-button ${saved?'saved':''}" data-watch="${c.id}" aria-label="${saved?'Remove':'Add'} ${esc(c.name)} ${saved?'from':'to'} watchlist" aria-pressed="${saved}">${saved?'♥':'♡'}</button>`;}
function playerTable(list,watch=true){return `<div class="panel table-wrap"><table><thead><tr><th>PLAYER ITEM</th><th>MARKET PRICE</th><th>24H CHANGE</th><th>TREND</th>${watch?'<th>WATCH</th>':''}</tr></thead><tbody>${list.map(c=>`<tr data-card="${c.id}" tabindex="0" role="button" aria-label="View ${esc(c.name)}"><td><div class="player-cell">${art(c,'table-art')}<span><b>${esc(c.name)}</b><small>${c.rating} ${c.position} · ${c.rarity}</small></span></div></td><td>${fmt(c.price)} <span style="color:#b592c8;font-size:8px">coins</span></td><td>${movement(c)}</td><td><div class="sparkline">${svgChart(c,true)}</div></td>${watch?`<td>${watchButton(c)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function spotlight(c){const values=series(c);return `<section class="panel"><div class="panel-header"><h3>Card spotlight</h3><span class="microtag">DEMO · CONSOLE</span></div><div class="card-spotlight">${art(c)}<div class="spotlight-meta"><span class="microtag">${c.rating} ${c.position} · ${c.rarity}</span><div class="spotlight-name">${esc(c.name)}</div><div class="spotlight-desc">${esc(c.club)} · ${esc(c.nation)}</div><div class="price-line"><span class="value">${fmt(c.price)}</span><span class="movement" style="${c.change<0?'background:#442036;color:var(--coral)':''}">${c.change>0?'+':''}${c.change}%</span></div><div class="panel-sub">coins · simulated market estimate</div></div></div><div class="chart-controls"><span class="chart-label">PRICE HISTORY</span><div class="segments">${['6h','24h','7d'].map(t=>`<button data-tf="${t}" class="${timeframe===t?'active':''}">${t}</button>`).join('')}</div></div><div class="chart" data-chart="${c.id}">${svgChart(c)}<span class="chart-tooltip"></span></div><div class="chart-axis"><span>${timeframe} ago</span><span>Illustrative series</span><span>Now</span></div><div class="chart-bottom"><span>Period low <b>${fmt(Math.min(...values))}</b></span><span>Period high <b>${fmt(Math.max(...values))}</b></span><span>Market <b>Console</b></span></div><div class="spotlight-actions"><button class="primary" data-newalert="${c.id}">Set price alert ↗</button><button class="secondary" data-watch="${c.id}">${state.watch.includes(c.id)?'♥ Watching':'♡ Watch card'}</button></div></section>`;}
function recentAlerts(){return `<section class="panel"><div class="panel-header"><div><h3>Your price alerts</h3><p class="panel-sub">The next move is yours.</p></div><button class="link-button" data-go="alerts">View all ↗</button></div><div style="height:10px"></div>${state.alerts.slice(0,4).map(a=>{const c=card(a.card);return `<div class="recent-alert"><span class="alert-symbol">${a.direction==='below'?'↘':'↗'}</span><div class="alert-info"><b>${esc(c.short)}</b><p>${a.direction==='below'?'At or below':'At or above'} ${fmt(a.target)} coins</p></div><span class="status-pill ${a.state==='paused'?'paused':''}">${a.state==='paused'?'Paused':'Watching'}</span></div>`;}).join('')||'<div class="empty"><b>Find your price.</b>Create your first personal alert.</div>'}<div class="activity-footer">Saved locally in this preview.<br>Connect Discord to enable private notifications.</div><div style="padding:0 20px 19px"><button class="secondary full" data-newalert="${selected}" style="margin-top:0">＋ Create an alert</button></div></section>`;}
function overview(){return header('YOUR MARKET. YOUR NEXT MOVE.','A better view of the game.','Your Ultimate Team tools, all in one workspace.',`<button class="primary" data-newalert="${selected}">Create price alert <span>＋</span></button>`)+`<div class="stats"><div class="stat"><div class="stat-top">Demo catalogue <span class="stat-icon">▤</span></div><div class="value">${cards.length} cards</div><div class="stat-bottom">Explore search, charts & artwork</div></div><div class="stat"><div class="stat-top">Active alerts <span class="stat-icon">◷</span></div><div class="value">${state.alerts.filter(a=>a.state==='active').length.toString().padStart(2,'0')}</div><div class="stat-bottom"><span class="positive">Personal targets</span> · local preview</div></div><div class="stat"><div class="stat-top">Your watchlist <span class="stat-icon">♡</span></div><div class="value">${state.watch.length.toString().padStart(2,'0')}</div><div class="stat-bottom">${fmt(state.watch.reduce((sum,id)=>sum+card(id).price,0))} coins combined</div></div><div class="stat"><div class="stat-top">Price source <span class="stat-icon">⌁</span></div><div class="value" style="font-size:21px;padding:5px 0">Demo mode</div><div class="stat-bottom">Production database awaiting connection</div></div></div><div class="main-grid">${spotlight(card(selected))}${recentAlerts()}</div><section class="bottom-section"><div class="section-bar"><h3>On the radar <span style="font-size:10px;color:#ac88c4;font-weight:400;margin-left:9px">A little movement. A lot of possibility.</span></h3><button class="link-button" data-go="market">Market movers ↗</button></div>${playerTable([...cards].sort((a,b)=>Math.abs(b.change)-Math.abs(a.change)).slice(0,4))}</section>`;}
function explorer(watch=false){const list=cards.filter(c=>(!watch||state.watch.includes(c.id))&&`${c.name} ${c.club} ${c.position} ${c.rarity}`.toLowerCase().includes(query.toLowerCase()));return header(watch?'YOUR SAVED CARDS':'FIND YOUR NEXT CARD',watch?'Keep an eye on the ones you want.':'Every card has a story.',watch?'Your saved cards, prices and movements together.':'Search exact versions. Explore the data. Choose your moment.',`<button class="primary" data-newalert="${selected}">New price alert <span>＋</span></button>`)+`<div class="searchbar"><span>⌕</span><input id="player-search" type="search" placeholder="Search players, positions or clubs…" value="${esc(query)}" aria-label="Search players"><select id="market-selector" aria-label="Market"><option value="console">Console · demo</option></select></div><div class="explorer-grid"><div><div class="small-cards">${list.map(c=>`<button class="player-tile ${selected===c.id?'selected':''}" data-select="${c.id}">${art(c)}<span><b>${esc(c.name)}</b><p>${c.rating} ${c.position} · ${c.club}</p><strong>${fmt(c.price)}</strong><span style="font-size:9px;margin-left:6px">${movement(c)}</span></span></button>`).join('')||'<div class="empty"><b>No matching cards.</b>Try another player or save cards to your watchlist.</div>'}</div><div class="panel compare-panel"><h3>Card attributes · ${esc(card(selected).short)}</h3><div class="compare-grid">${card(selected).stats.map((v,i)=>`<div class="compare-stat"><b>${v}</b>${['PAC','SHO','PAS','DRI','DEF','PHY'][i]}</div>`).join('')}</div><div class="panel-sub">Demo attributes. Lavia and Witzig artwork comes from your supplied catalogue.</div></div></div>${spotlight(card(selected))}</div>`;}
function alertsPage(){return header('YOUR PRIVATE MARKET WATCH','Ready when the price is.','Manage your targets. Notifications belong in your DMs.',`<button class="primary" data-newalert="${selected}">Create alert <span>＋</span></button>`)+`<div class="panel table-wrap"><table class="alert-table"><thead><tr><th>PLAYER</th><th>CONDITION</th><th>TARGET</th><th>CURRENT DEMO PRICE</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${state.alerts.map(a=>{const c=card(a.card);return `<tr><td><div class="player-cell">${art(c,'table-art')}<span><b>${esc(c.name)}</b><small>${c.rating} ${c.position} · Console demo</small></span></div></td><td>${a.direction==='below'?'At or below':'At or above'}</td><td>${fmt(a.target)}</td><td>${fmt(c.price)}</td><td><span class="status-pill ${a.state==='paused'?'paused':''}">${a.state==='paused'?'Paused':'Watching'}</span></td><td><div class="action-cell"><button class="mini-button" data-pause="${a.id}">${a.state==='paused'?'Resume':'Pause'}</button><button class="mini-button danger" data-delete="${a.id}">Delete</button></div></td></tr>`;}).join('')}</tbody></table>${!state.alerts.length?'<div class="empty"><b>No alerts yet.</b>Set your first target to start watching.</div>':''}</div><div class="banner-note">Alerts created here are local demonstrations. The Discord service includes real threshold checks, data freshness rules and retried DM delivery once configured.</div>`;}
function market(){let list=[...cards];if(sort==='risers')list=list.filter(c=>c.change>=0).sort((a,b)=>b.change-a.change);else if(sort==='fallers')list=list.filter(c=>c.change<0).sort((a,b)=>a.change-b.change);else list.sort((a,b)=>Math.abs(b.change)-Math.abs(a.change));return header('READ THE MOVEMENT','The market never stands still.','Follow the biggest moves in the demo catalogue.')+`<div class="tabs">${[['all','All movement'],['risers','↗ Risers'],['fallers','↘ Fallers']].map(([v,l])=>`<button class="${sort===v?'active':''}" data-sort="${v}">${l}</button>`).join('')}</div>${playerTable(list)}<div class="banner-note">Illustrative 24h movements. Production rankings will be calculated from the connected FC27 price history, with freshness checks and minimum observation counts.</div>`;}
function feeds(){return header('THE RIGHT UPDATES. THE RIGHT CHANNELS.','Your server, in the know.','Curate FC news and creator updates with your own presentation.',`<button class="primary" id="add-feed">Add a feed <span>＋</span></button>`)+`<div class="feed-list">${state.feeds.map(f=>`<section class="feed-card"><div class="feed-top"><div class="source-icon">${f.provider==='X account'?'𝕏':f.provider==='YouTube'?'▷':'◉'}</div><div><h3>${esc(f.name)}</h3><p>${esc(f.source)} · ${esc(f.provider)}</p></div><button class="toggle ${f.enabled?'on':''}" data-feed-toggle="${f.id}" role="switch" aria-checked="${f.enabled}" aria-label="Toggle ${esc(f.name)}"></button></div><div class="feed-routing"><span>POST TO</span><span class="channel"># ${esc(f.channel)}</span></div><div class="feed-actions"><span class="status-pill ${f.enabled?'':'paused'}">${f.enabled?'Enabled in demo':'Paused'}</span><button class="mini-button danger" data-feed-delete="${f.id}">Remove</button></div></section>`).join('')}</div><div class="banner-note">Feed settings are saved locally. RSS, X API and webhook ingestion are planned next; enabling a demo feed does not publish messages.</div>`;}
function embedPreview(){const c=card(selected);return `<div class="discord-preview"><div class="preview-label">DISCORD EMBED · LIVE STYLE PREVIEW</div><div class="discord-post"><div class="bot-avatar">f↗</div><div><div class="bot-name" id="preview-name">${esc(state.brand.name)}<span class="bot-badge">APP</span><span class="bot-time">Today at 15:24</span></div><div class="embed"><div class="embed-head"><div><h4>${esc(c.name)} · ${c.rating}</h4><small>${c.position} · ${c.rarity} · Console</small></div>${c.image?art(c):'<span class="placeholder-art">'+c.rating+'</span>'}</div><div class="embed-fields"><div><label>MARKET ESTIMATE</label><b>${fmt(c.price)} coins</b></div><div><label>24H MOVEMENT</label><b>${c.change>0?'+':''}${c.change}%</b></div><div><label>DATA MODE</label><b>Demonstration</b></div><div><label>CARD VERSION</label><b>FC27 · ${c.rating} ${c.position}</b></div></div><div class="embed-chart">${svgChart(c)}</div><div class="embed-footer" id="preview-footer">${esc(state.brand.footer)}</div></div><div class="discord-buttons"><span>Set price alert</span><span>Price history</span><span>Watch card</span></div></div></div></div>`;}
function appearance(){return header('MAKE IT FEEL LIKE YOURS','Built for your community.','Give every FutBot result your server’s own look and voice.')+`<div class="explorer-grid"><section class="panel form-panel"><h3>Server identity</h3><form id="brand-form"><label>Display name<input name="name" value="${esc(state.brand.name)}" maxlength="50" required></label><div class="form-grid"><label>Embed accent<input name="accent" type="color" value="${esc(state.brand.accent)}"></label><label>Preview card<select name="card">${cards.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label></div><label>Footer text<input name="footer" value="${esc(state.brand.footer)}" maxlength="120" required></label><button class="primary full" type="submit">Save appearance <span>✓</span></button></form><p class="field-hint">Changes update this preview and are stored in this browser.</p></section><div id="embed-preview">${embedPreview()}</div></div>`;}
function health(){return header('THE ENGINE BEHIND THE EMBEDS','Know where your data stands.','Connection requirements and the data contract for the first build.')+`<div class="connection-grid"><section class="panel connection"><span class="eyebrow">01 · PRICE SOURCE</span><h3>Existing PostgreSQL database</h3><p>The bot reads your catalogue and price history using a dedicated read-only pool.</p><div class="connection-code">futgg_players → cards & images<br>futgg_bin_history → prices & charts<br>FC27 · configured market only</div><div class="notice">Awaiting PRICE_DATABASE_URL in the bot service.</div></section><section class="panel connection"><span class="eyebrow">02 · DISCORD</span><h3>FutBot application</h3><p>The source registers price, alert, myalerts, removealert and tax commands. No message-content intent required.</p><div class="connection-code">DISCORD_TOKEN<br>DISCORD_GUILD_ID<br>APP_DATABASE_URL</div><div class="notice">Create the new Discord application and configure service secrets to enable it.</div></section></div><section class="panel bottom-section"><div class="panel-header"><h3>Build readiness</h3><span class="microtag">v0.1</span></div><div style="height:12px"></div>${[['Interactive dashboard','Demo ready'],['Stored card artwork','Catalogue examples'],['Price & history adapter','Implemented · not connected'],['Discord commands & chart renderer','Implemented · not connected'],['Personal alerts & delivery retries','Implemented · not connected'],['Discord OAuth admin login','Next build'],['Social feed ingestion','Next build'],['Premium billing','Planned']].map(([a,b])=>`<div class="readiness"><span>${a}</span><span class="badge-warning">${b}</span></div>`).join('')}</section>`;}
function page(){return names[location.hash.slice(1)]?location.hash.slice(1):'overview';}
function render(){const p=page();$('#crumb').textContent=names[p];$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===p));$('#main').innerHTML=({overview,players:()=>explorer(),alerts:alertsPage,watchlist:()=>explorer(true),market,feeds,appearance,health})[p]();applyBrand();persist();bindMain();}
function openAlert(id){const c=card(id);$('#alert-card').innerHTML=cards.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)} · ${c.rating} ${c.position}</option>`).join('');$('#alert-form').elements.target.value=Math.max(1,Math.round(c.price*.9));$('#alert-dialog').showModal();}
function toggleWatch(id){state.watch=state.watch.includes(id)?state.watch.filter(v=>v!==id):[...state.watch,id];persist();render();toast(state.watch.includes(id)?'Card added to your watchlist.':'Card removed from your watchlist.');}
function bindMain(){
 $$('[data-go]').forEach(b=>b.onclick=()=>{location.hash=b.dataset.go;});$$('[data-newalert]').forEach(b=>b.onclick=()=>openAlert(b.dataset.newalert));
 $$('[data-watch]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleWatch(b.dataset.watch);});
 $$('[data-card]').forEach(r=>{const select=()=>{selected=r.dataset.card;query='';location.hash='players';if(page()==='players')render();};r.onclick=select;r.onkeydown=e=>{if(e.target!==r)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};});
 $$('[data-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.select;render();});
 $$('[data-tf]').forEach(b=>b.onclick=()=>{timeframe=b.dataset.tf;render();});
 $$('[data-sort]').forEach(b=>b.onclick=()=>{sort=b.dataset.sort;render();});
 $$('[data-pause]').forEach(b=>b.onclick=()=>{const a=state.alerts.find(a=>a.id===b.dataset.pause);a.state=a.state==='active'?'paused':'active';persist();render();toast(a.state==='paused'?'Alert paused.':'Alert resumed.');});
 $$('[data-delete]').forEach(b=>b.onclick=()=>{state.alerts=state.alerts.filter(a=>a.id!==b.dataset.delete);persist();render();toast('Alert deleted.');});
 $$('[data-feed-toggle]').forEach(b=>b.onclick=()=>{const f=state.feeds.find(f=>f.id===b.dataset.feedToggle);f.enabled=!f.enabled;persist();render();toast(f.enabled?'Feed enabled in demo.':'Feed paused.');});
 $$('[data-feed-delete]').forEach(b=>b.onclick=()=>{state.feeds=state.feeds.filter(f=>f.id!==b.dataset.feedDelete);persist();render();toast('Feed removed from demo.');});
 if($('#add-feed'))$('#add-feed').onclick=()=>$('#feed-dialog').showModal();
 const search=$('#player-search');if(search)search.oninput=()=>{query=search.value;const pos=search.selectionStart;render();const next=$('#player-search');next.focus();next.setSelectionRange?.(pos,pos);};
 const form=$('#brand-form');if(form){form.oninput=()=>{const f=new FormData(form);state.brand={name:String(f.get('name')),accent:String(f.get('accent')),footer:String(f.get('footer'))};selected=String(f.get('card'));applyBrand();$('#embed-preview').innerHTML=embedPreview();};form.onsubmit=e=>{e.preventDefault();persist();toast('Appearance saved in this browser.');};}
 $$('[data-chart]').forEach(el=>{el.onpointermove=e=>{const c=card(el.dataset.chart),v=series(c),box=el.getBoundingClientRect(),pct=Math.min(1,Math.max(0,(e.clientX-box.left)/box.width)),index=Math.round(pct*(v.length-1)),tip=el.querySelector('.chart-tooltip');tip.textContent=fmt(v[index])+' coins · demo';tip.style.display='block';tip.style.left=Math.min(68,Math.max(2,pct*100))+'%';};el.onpointerleave=()=>{el.querySelector('.chart-tooltip').style.display='none';};});
}
$('#alert-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),target=Number(f.get('target'));if(!Number.isInteger(target)||target<1||target>15000000){toast('Enter a whole coin amount between 1 and 15,000,000.');return;}state.alerts.unshift({id:crypto.randomUUID(),card:String(f.get('card')),direction:String(f.get('direction')),target,state:'active'});persist();$('#alert-dialog').close();render();toast('Alert saved. Demo mode does not send Discord messages.');};
$('#feed-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);state.feeds.push({id:crypto.randomUUID(),name:String(f.get('name')),provider:String(f.get('provider')),source:String(f.get('source')),channel:String(f.get('channel')).replace(/^#\s*/,''),enabled:true});persist();$('#feed-dialog').close();e.currentTarget.reset();render();toast('Feed saved in this demo workspace.');};
$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#demo-help').onclick=()=>$('#info-dialog').showModal();$('#reset-demo').onclick=()=>{state=structuredClone(defaultState);persist();$('#info-dialog').close();render();toast('Demo workspace reset.');};$('#server-switch').onclick=()=>toast('FUTBank is the example workspace. Server switching follows Discord OAuth.');$('#search-focus').onclick=()=>{location.hash='players';requestAnimationFrame(()=>$('#player-search')?.focus());};$('#mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('dialog[open]')){e.preventDefault();location.hash='players';requestAnimationFrame(()=>$('#player-search')?.focus());}});window.addEventListener('hashchange',()=>{$('.sidebar').classList.remove('open');render();});render();
